using System.Net.WebSockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace SoloCamera.Windows;
/// <summary>
/// Local OBS WebSocket client for authenticated scene/source setup and virtual-camera
/// control. It refuses scene reconfiguration during an active recording or stream.
/// </summary>
public sealed class ObsBridge:IDisposable {
 readonly ClientWebSocket socket=new(); readonly SemaphoreSlim gate=new(1); readonly CancellationTokenSource stop=new();
 async Task<JsonElement> Receive(){using var ms=new MemoryStream();var buffer=new byte[65536];WebSocketReceiveResult r;do{r=await socket.ReceiveAsync(new ArraySegment<byte>(buffer),stop.Token).WaitAsync(TimeSpan.FromSeconds(10));if(r.MessageType==WebSocketMessageType.Close)throw new IOException("OBS disconnected");ms.Write(buffer,0,r.Count);if(ms.Length>8_000_000)throw new IOException("OBS response too large");}while(!r.EndOfMessage);return JsonDocument.Parse(ms.ToArray()).RootElement.Clone();}
 async Task Send(object value)=>await socket.SendAsync(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(value)),WebSocketMessageType.Text,true,stop.Token);
 public event Action<JsonElement>? Event;
 public async Task Connect(int port,string password,int subscriptions=0){await socket.ConnectAsync(new Uri($"ws://127.0.0.1:{port}"),stop.Token).WaitAsync(TimeSpan.FromSeconds(5));var hello=(await Receive()).GetProperty("d");string? authentication=null;if(hello.TryGetProperty("authentication",out var a)){string secret=Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(password+a.GetProperty("salt").GetString())));authentication=Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(secret+a.GetProperty("challenge").GetString())));}await Send(new{op=1,d=new{rpcVersion=1,authentication,eventSubscriptions=subscriptions}});if((await Receive()).GetProperty("op").GetInt32()!=2)throw new IOException("OBS authentication failed");}
 public async Task<JsonElement> Request(string type,object? data=null){await gate.WaitAsync();try{string id=Guid.NewGuid().ToString();await Send(new{op=6,d=new{requestType=type,requestId=id,requestData=data??new{}}});for(;;){var r=await Receive();if(r.GetProperty("op").GetInt32()==5){Event?.Invoke(r.GetProperty("d"));continue;}if(r.GetProperty("op").GetInt32()!=7)continue;var d=r.GetProperty("d");if(d.GetProperty("requestId").GetString()!=id)continue;var status=d.GetProperty("requestStatus");if(!status.GetProperty("result").GetBoolean())throw new IOException(status.TryGetProperty("comment",out var c)?c.GetString():type+" failed");return d.TryGetProperty("responseData",out var result)?result.Clone():default;}}finally{gate.Release();}}
 public async Task Setup(string url){foreach(string operation in new[]{"GetRecordStatus","GetStreamStatus"})if((await Request(operation)).GetProperty("outputActive").GetBoolean())throw new IOException("Stop OBS recording and streaming before setting up webcam scenes.");var settings=await Request("GetVideoSettings");int width=settings.GetProperty("baseWidth").GetInt32(),height=settings.GetProperty("baseHeight").GetInt32();var scenes=(await Request("GetSceneList")).GetProperty("scenes").EnumerateArray().Select(x=>x.GetProperty("sceneName").GetString()).ToHashSet();var inputs=(await Request("GetInputList")).GetProperty("inputs").EnumerateArray().Select(x=>x.GetProperty("inputName").GetString()).ToHashSet();for(int i=-1;i<4;i++){string name=i<0?"Solo Camera · Program":$"Solo Camera · Camera {i+1}";string input=name+" Feed";if(!scenes.Contains(name))await Request("CreateScene",new{sceneName=name});var source=new{url=i<0?url:url+"?camera="+i,width,height,fps=30,reroute_audio=true,shutdown=true,restart_when_active=true};if(inputs.Contains(input))await Request("SetInputSettings",new{inputName=input,inputSettings=source,overlay=true});else await Request("CreateInput",new{sceneName=name,inputName=input,inputKind="browser_source",inputSettings=source,sceneItemEnabled=true});}await Request("SetCurrentProgramScene",new{sceneName="Solo Camera · Program"});}
 public async Task StartWebcam(){var previous=await Request("GetVirtualCamStatus");if(previous.GetProperty("outputActive").GetBoolean())throw new IOException("The OBS virtual camera is already in use. Stop it in OBS before starting this session.");await Request("StartVirtualCam");for(int i=0;i<30;i++){await Task.Delay(200);if((await Request("GetVirtualCamStatus")).GetProperty("outputActive").GetBoolean())return;}throw new IOException("OBS did not start its virtual camera. Check OBS for an output error and close other OBS instances using the virtual camera.");}
 public void Dispose(){stop.Cancel();socket.Dispose();}
}


